contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        string memory before = c.symbol();
        bool reverted;
        string memory returned;
        try c.symbol() returns (string memory s) {
            reverted = false;
            returned = s;
        } catch {
            reverted = true;
        }
        string memory afterSymbol = c.symbol();
        assert(
            !reverted
                ? keccak256(bytes(returned)) == keccak256(bytes(afterSymbol))
                : keccak256(bytes(before)) == keccak256(bytes(afterSymbol))
        );
    }

    receive() external payable {}
}

