contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address pool, address member, uint256 amount) public {
        // The only way to write mapSynth_LPDebt[msg.sender] is mintSynth, which is
        // gated by onlyPool: the caller must be a curated pool. Since InvMutTest
        // is the msg.sender for every c call, use c.getmapAddress_LPDebt as the
        // deciding read and assert the accounting invariant it must uphold:
        // a fresh c has zero debt, and after the gated mintSynth the pool's debt
        // is exactly the minted amount while the receiver's synth balance is amount.
        uint256 debtBefore = c.getmapAddress_LPDebt(pool);
        uint256 balBefore = c.balanceOf(member);

        bool reverted;
        try c.mintSynth(member, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 debtAfter = c.getmapAddress_LPDebt(pool);
        uint256 balAfter = c.balanceOf(member);

        if (reverted) {
            // A reverted gated call must leave the debt accounting untouched and
            // must not mint synth to the member.
            assert(debtAfter == debtBefore && balAfter == balBefore);
        } else {
            // A successful mintSynth credits debt[msg.sender=this contract] by the
            // exact amount parameter, and mints the same amount of synth to member.
            assert(debtAfter == debtBefore + amount && balAfter == balBefore + amount);
        }
    }
}

