        uint returned = c.mintSynth(member, amount);
        uint debtAfter = c.getmapAddress_LPDebt(address(this));

        assert(returned == amount && debtAfter == debtBefore + priorDebtIncrement + amount);
    }

    receive() external payable {}
}

