contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address spender, uint256 sub) public {
        require(spender != address(0), "bad spender");
        uint256 beforeAllowance = c.allowance(address(this), spender);

        bool reverted;
        bool result;
        try c.decreaseAllowance(spender, sub) returns (bool r) {
            result = r;
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterAllowance = c.allowance(address(this), spender);

        assert(
            reverted
                ? (beforeAllowance < sub && afterAllowance == beforeAllowance)
                : (result == true && beforeAllowance >= sub && afterAllowance == beforeAllowance - sub)
        );
    }
